# -*- coding: utf-8 -*-
from lesson_authoring import entry as E
from author_batch200_root_bio_a import B,H
WF=[
E('biotech','英 /ˈbaɪəʊtek/；美 /ˈbaɪoʊtek/','生物技术〔简称〕；生物技术公司或行业','把 biotechnology 这个长词缩短，用来谈技术、企业或整个行业。','biotechnology 的截短形式；也能从 bio + tech 看出“生物与技术”的组合。',B+[['英语 biotechnology → biotech','生物技术 → 简称；再指相关公司、行业']],'She works in biotech 通常说她在生物技术行业工作。a biotech 则可指一家生物技术公司。它强调技术和产业方向，不一定是制药公司，也可能涉及农业、材料或其他生物应用。','work in biotech；a biotech company；the biotech industry。','biotech 是 biotechnology 的简称；biochem 是 biochemistry 的简称，一个偏技术应用，一个是学科名称。',('She works for a small biotech company.','她在一家小型生物技术公司工作。'),('The project brought together researchers from biotech and agriculture.','项目集合了生物技术和农业领域的研究人员。'),sources=['https://en.wiktionary.org/wiki/biotech','https://dictionary.cambridge.org/dictionary/english/biotech']),
E('biotechnological','英 /ˌbaɪəʊteknəˈlɒdʒɪkəl/；美 /ˌbaɪoʊteknəˈlɑːdʒɪkəl/','生物技术的','说明某种方法或应用，利用了生物系统及相关技术。','bio- + technological，也与 biotechnology 的 -ical 形容词形式对应。',H(B,'英语 bio- + technological → biotechnological','与生物技术相关的'),'a biotechnological process 可以利用细胞、酶或其他生物成分完成生产或处理任务。这个词没有规定必须改造基因；传统发酵与现代细胞工程都可能处在生物技术的大范围内。','biotechnological applications；a biotechnological process；biotechnological research。','biotechnological 说明技术领域；biological 更宽，只说与生物有关。',('The enzyme has several biotechnological applications.','这种酶有几种生物技术用途。'),('The company developed a new biotechnological process.','公司开发了一种新的生物技术工艺。'),sources=['https://en.wiktionary.org/wiki/biotechnological','https://www.merriam-webster.com/dictionary/biotechnology']),
E('bioreactor','英 /ˌbaɪəʊriˈæktə/；美 /ˌbaɪoʊriˈæktər/','生物反应器','给细胞或酶一个可控制的工作空间，让生物过程完成预定任务。','bio-“生物” + reactor“反应器”，并不是“生物核反应堆”。',H(B,'英语 bio- + reactor → bioreactor','容纳并控制生物反应的装置'),'bioreactor 可以用于发酵、细胞培养或其他生物过程。它不只是一只罐子：设计还要考虑生物过程需要的条件及监测。不同用途的装置结构不同，不必都很大。','a laboratory bioreactor；a fermentation bioreactor；a bioreactor system。','reactor 泛指反应装置；bioreactor 特别强调生物参与的过程。看到 reactor 不应一律想到核能。',('The cells were grown in a laboratory bioreactor.','这些细胞在实验室生物反应器中培养。'),('The team monitored the bioreactor throughout the experiment.','团队在整个实验过程中监测了生物反应器。'),sources=['https://en.wiktionary.org/wiki/bioreactor','https://www.merriam-webster.com/dictionary/bioreactor']),
E('biosensor','英 /ˈbaɪəʊsensə/；美 /ˈbaɪoʊˌsensər/','生物传感器','让某种生物识别或反应先发现目标，再把结果变成可读信号。','bio-“生物” + sensor“传感器”，现代测量技术构词。',H(B,'英语 bio- + sensor → biosensor','利用生物成分或反应进行检测的传感器'),'严格的技术用法常强调酶、抗体等生物识别成分与信号转换部分的结合。例如某些血糖传感器利用酶相关反应检测葡萄糖。大众语境也可能泛指测生理信号的装置，不能把所有可穿戴设备都按同一严格定义归类。','an enzyme biosensor；a glucose biosensor；biosensor development。','biosensor 的技术核心不只是“放在人身上”，还要看它是否利用生物识别、反应或相关信号机制。',('The biosensor detects glucose in the sample.','这个生物传感器检测样本中的葡萄糖。'),('The researchers improved the biosensor’s sensitivity.','研究者提高了生物传感器的灵敏度。'),sources=['https://en.wiktionary.org/wiki/biosensor','https://goldbook.iupac.org/terms/view/B00663/PDF','https://goldbook.iupac.org/terms/view/09071']),
E('biomolecule','英 /ˌbaɪəʊˈmɒlɪkjuːl/；美 /ˌbaɪoʊˈmɑːlɪkjuːl/','生物分子','把生命系统拆到分子层面，蛋白质、糖、脂质等都是其中的材料和参与者。','bio-“生物” + molecule“分子”，近代科学组合词。',H(B,'英语 bio- + molecule → biomolecule','生命系统中的有机分子，常包括大分子'),'biomolecule 不是一个活细胞，而是生物体内的分子。蛋白质、核酸等是常见例子，小分子也可能包括在内。词前的 bio- 指它与生命系统的联系，并不是说这个分子自己会呼吸、繁殖。','a complex biomolecule；the structure of a biomolecule；interactions between biomolecules。','biomolecule 是分子；microorganism 是微生物。两者尺度和组织层次不同。',('The technique reveals the structure of a biomolecule.','这项技术揭示了一个生物分子的结构。'),('Biomolecules interact in complex networks inside cells.','生物分子在细胞内部通过复杂网络相互作用。'),sources=['https://www.merriam-webster.com/dictionary/biomolecule','https://en.wiktionary.org/wiki/biomolecule']),
E('biomolecular','英 /ˌbaɪəʊməˈlekjʊlə/；美 /ˌbaɪoʊməˈlekjələr/','生物分子的；涉及生物分子层面的','把问题缩到分子怎样相遇、结合、变化这一层来研究。','bio- + molecular“分子的”，与 biomolecule 词族对应。',H(B,'英语 bio- + molecular → biomolecular','涉及生命系统中分子的'),'biomolecular interactions 可以说蛋白质与核酸、蛋白质与其他分子的相互作用。biomolecular science 是研究这些结构和过程的领域，不等于只研究DNA。','biomolecular structure；biomolecular interactions；biomolecular engineering。','biomolecular 说明分子层面；biomechanical 说明力学角度。两个角度也可能用于同一个问题。',('The paper describes a new method for studying biomolecular interactions.','论文介绍了一种研究生物分子相互作用的新方法。'),('The course focuses on biomolecular structure and function.','课程重点讨论生物分子的结构与功能。'),sources=['https://www.merriam-webster.com/dictionary/biomolecule','https://en.wiktionary.org/wiki/biomolecular']),
E('biopolymer','英 /ˌbaɪəʊˈpɒlɪmə/；美 /ˌbaɪoʊˈpɑːlɪmər/','生物聚合物','很多小单元连成大分子，而这些大分子由生物产生。','bio-“生物” + polymer“聚合物”，对应生物来源的大分子。',H(B,'英语 bio- + polymer → biopolymer','由生物形成的聚合物'),'蛋白质、核酸和多糖属于典型 biopolymers。材料宣传里这个词有时用得更宽，因此仍要看具体成分。生物来源、可生物降解、可堆肥是不同判断，不能看到 biopolymer 就把三件事画等号。','a natural biopolymer；biopolymer production；a biopolymer material。','biopolymer 指材料的生物来源或相应类别；biodegradable 指能否经生物作用分解。',('Cellulose is a widely occurring biopolymer.','纤维素是一种广泛存在的生物聚合物。'),('The researchers tested the strength of the biopolymer.','研究者测试了这种生物聚合物的强度。'),sources=['https://goldbook.iupac.org/terms/view/B00661','https://en.wiktionary.org/wiki/biopolymer']),
E('biodegradation','英 /ˌbaɪəʊˌdeɡrəˈdeɪʃən/；美 /ˌbaɪoʊˌdeɡrəˈdeɪʃən/','生物降解','材料被生物活动一步步分解，不只是被磨成更小的碎片。','bio-“生物作用” + degradation“降解”，其中 degradation 更早接“降级、往下”的词义。',H(B,'英语 bio- + degradation → biodegradation','经生物作用分解材料的过程'),'biodegradation 的速度与程度取决于材料和环境条件。一个东西裂开、变脆或碎成微粒，并不能单独证明发生了充分的生物降解。这个词描述过程，不能省略过程所需条件。','the rate of biodegradation；biodegradation in soil；test for biodegradation。','fragmentation 只是碎裂；biodegradation 涉及生物作用造成的分解。composting 还涉及特定堆肥条件。',('The experiment measured the rate of biodegradation in soil.','实验测量了材料在土壤中的生物降解速度。'),('Temperature affected biodegradation in the samples.','温度影响了样本中的生物降解。'),sources=['https://en.wiktionary.org/wiki/biodegradation','https://www.epa.gov/trash-free-waters/frequently-asked-questions-about-plastic-recycling-and-composting']),
E('biodegrade','英 /ˌbaɪəʊdɪˈɡreɪd/；美 /ˌbaɪoʊdɪˈɡreɪd/','发生生物降解；被生物作用分解','让微生物等生物活动真正参与，把材料逐步拆解。','bio- + degrade“分解、降解”；与 biodegradation、biodegradable 形成同一现代词族，不凭后缀推定各词出现先后。',H(B,'英语 bio- + degrade → biodegrade','经生物作用发生分解'),'The material biodegrades 说材料能够在相关条件下发生这种过程。读到“多久能降解”，还要看是在土壤、水中还是工业处理条件下；不能把某个条件下的结果自动推广到所有环境。','biodegrade in soil；biodegrade under certain conditions；biodegrade slowly。','biodegrade 不等于 dissolve“溶解”。盐溶进水里，并不因此成为一次生物降解。',('The material biodegrades under the specified conditions.','这种材料会在指定条件下发生生物降解。'),('Some substances biodegrade more slowly in cold environments.','有些物质在寒冷环境中生物降解得更慢。'),sources=['https://en.wiktionary.org/wiki/biodegrade','https://www.merriam-webster.com/dictionary/biodegrade','https://www.epa.gov/trash-free-waters/frequently-asked-questions-about-plastic-recycling-and-composting']),
E('biocompatible','英 /ˌbaɪəʊkəmˈpætəbəl/；美 /ˌbaɪoʊkəmˈpætəbəl/','具有生物相容性的','材料放到预定的生物环境里，能完成用途，并得到可接受的组织反应。','bio-“生物系统” + compatible“相容的”，不是“由生物制成”的同义词。',H(B,'英语 bio- + compatible → biocompatible','与特定生物应用相容的'),'biocompatible material 常用于医疗材料讨论。相容性与接触位置、持续时间、加工方式和用途有关，不能脱离情境简单说一块材料“对所有人体部位永远安全”。它也不必来自天然来源。','a biocompatible material；a biocompatible coating；biocompatible for a specific use。','biocompatible 关注接触生物系统后的反应；biodegradable 关注能否被生物作用分解。',('The device uses a biocompatible coating.','这个装置使用了具有生物相容性的涂层。'),('The material was evaluated to determine whether it was biocompatible for the intended use.','研究评估了这种材料在预定用途下是否具有生物相容性。'),sources=['https://www.merriam-webster.com/dictionary/biocompatible','https://www.fda.gov/medical-devices/biocompatibility-assessment-resource-center/basics-biocompatibility-information-needed-assessment-fda']),
E('biocompatibility','英 /ˌbaɪəʊkəmˌpætəˈbɪləti/；美 /ˌbaɪoʊkəmˌpætəˈbɪləti/','生物相容性','考察材料与生命组织接触以后，双方是否能按预定用途合适地相处。','bio- + compatibility“相容性”；与 biocompatible 对应，但名词也可直接按两个成分分析。',H(B,'英语 bio- + compatibility → biocompatibility','材料或装置在具体应用中的生物相容程度'),'biocompatibility testing 不是只问材料有没有立刻杀死细胞，而是根据应用评价相关生物反应。接触皮肤的短时用品和长期植入物，所需考虑的情境不同。这个词强调的是一项综合性质。','assess biocompatibility；biocompatibility testing；the biocompatibility of a material。','biocompatibility 不是“人体不会作任何反应”；它关注在具体应用中是否产生合适、可接受的反应。',('The team assessed the material’s biocompatibility.','团队评估了材料的生物相容性。'),('Manufacturing changes can affect biocompatibility.','制造工艺的变化可能影响生物相容性。'),sources=['https://en.wiktionary.org/wiki/biocompatibility','https://www.merriam-webster.com/dictionary/biocompatibility','https://www.fda.gov/medical-devices/biocompatibility-assessment-resource-center/basics-biocompatibility-information-needed-assessment-fda']),
E('biofilm','英 /ˈbaɪəʊfɪlm/；美 /ˈbaɪoʊfɪlm/','生物膜；包裹在胞外基质中的微生物群体','许多微生物不再各自漂浮，而是一起住进自己形成的黏性结构里。','bio-“生物” + film“薄层、膜”，这里的 film 不是电影。',H(B,'英语 bio- + film → biofilm','微生物聚集并嵌入基质形成的结构'),'biofilm 常附着在表面，例如牙菌斑或水中物体表面的某些微生物层；也有其他组织形式。核心是微生物群体与包围它们的基质，不是一层普通塑料薄膜，也不等于单个细胞的细胞膜。','biofilm formation；a bacterial biofilm；a surface biofilm。','biofilm 是微生物群体形成的结构；cell membrane 是单个细胞的边界结构，中文都可能带“膜”却不是同一回事。',('A biofilm had formed on the submerged surface.','浸在水中的表面形成了一层生物膜。'),('The study examined how the biofilm changed over time.','研究考察了生物膜如何随时间变化。'),sources=['https://en.wiktionary.org/wiki/biofilm','https://journals.asm.org/doi/10.1128/jb.00118-19']),
]
